from pathlib import Path
from html import escape
out=Path(__file__).resolve().parent
pages=[]
def p(s): return '<p>'+s+'</p>'
def cmd(s): return '<pre>'+escape(s)+'</pre>'
def note(s): return '<aside>'+s+'</aside>'
def steps(items): return '<ol>'+''.join('<li>'+s+'</li>' for s in items)+'</ol>'
def page(title,*body): pages.append('<section><div class="eyebrow">UPDATA · ESP32 PHONE BRIDGE</div><h1>'+title+'</h1>'+''.join(body)+'</section>')
page('ESP32 to CRM<br>Setup without source code',p('<b>Mac • Windows PC • Linux | 13 November 2026</b>'),p('Use this guide to prepare an original ESP32, connect an Android SIM phone and verify real calling audio. End users do not need access to GitHub, the CRM repository, firmware source or ESP-IDF.'),note('Two separate downloads in CRM Setup guide: <b>Download gateway</b> installs the computer program; <b>Download ESP32 firmware</b> provides compiled images for a new board. Neither download flashes a board automatically.'),p('Connection: CRM ↔ internet ↔ computer gateway ↔ USB ↔ ESP32 ↔ Bluetooth hands-free ↔ Android SIM.'),p('Contents: 1 Equipment; 2 Gateway; 3 USB checks; 4 Flashing tools; 5 Chip checks and backup; 6 Flash compiled firmware; 7 CRM link; 8 Bluetooth and sound; 9 Daily use and moving computers; 10 Troubleshooting and release information.'),p('Use current files from the same approved CRM release. Project physical verification used macOS; Windows/Linux instructions still require real hardware and audio acceptance. Stop at an unexplained failure.'))
page('1. Equipment and preparation',steps(['Use an original ESP32-WROOM-32 / 32E / 32D with Classic Bluetooth. S2, S3, C3, C6 and H2 do not support this bridge. CP210x/CH34x identifies the USB adapter, not the ESP32 silicon.','Use a USB data cable, direct computer port, Android phone with an active SIM, calling credit and signal. Have a second phone you own available for testing.','Install an actively supported Node.js LTS version, 20 or newer, from nodejs.org/en/download. Choose the correct computer architecture. Reopen Terminal afterward.','Sign into CRM with AI Calling write permission or administrator access. Use your own phone card.','Before diagnostics or flashing, finish calls, stop gateway processes and any Mac login service, and close screen / Arduino Serial Monitor.']),cmd('node --version\nnpm --version'),p('For an already prepared board, try the USB check first. Normal reconnection does not need firmware flashing, BOOT or a new security key.'),note('Replace placeholders such as PHONE_ID and YOUR_CODE with values from the phone card. Use actual ports from discovery; Mac /dev/cu.usbserial-0001, Windows COM5 and Linux /dev/ttyUSB0 below are examples. Do not paste shell prompts or backslashes inside https://.'))
page('2. Install the computer gateway',steps(['Open AI Calling → Connections / Paired phones → Setup guide. Download gateway.','Extract the archive into a permanent folder you own. Open the package folder; it contains bin, src and package.json.','Mac: open Terminal, type cd followed by a space, drag the package folder from Finder and press Enter. Windows: open cmd.exe, type cd /d followed by the quoted package path. Linux: open a terminal in the package folder.','Run the installation command below and wait for it to finish.']),cmd('npm ci --omit=dev\nnode bin/esp32-probe.mjs ports'),p('Keep this folder and Node installation in place. Each phone needs its own prepared bridge, USB port, profile and gateway process.'),note('This installs the gateway only. Do not search for firmware source in this package. A separate compiled firmware download is available for new boards.'))
page('3. Verify the USB connection',p('With the gateway stopped, list ports and use the actual bridge port:'),cmd('node bin/esp32-probe.mjs ports'),p('Mac example:'),cmd('node bin/esp32-probe.mjs info --port /dev/cu.usbserial-0001'),p('Windows example:'),cmd('node bin/esp32-probe.mjs info --port COM5'),p('Linux example:'),cmd('node bin/esp32-probe.mjs info --port /dev/ttyUSB0'),steps(['Firmware information appears: USB handshake works; skip flashing and continue at section 7.','Resource busy: identify and close the program holding the port. On Mac use lsof as below. Do not run the gateway and probe together.','No bridge listed: try a known data cable, direct USB port and the adapter manufacturer’s driver.','[no_reply]: release BOOT, press EN/RESET once, wait five seconds, retry. If it still fails, inspect the bootloader and firmware using sections 4–6. A timeout alone does not prove reflashing is necessary.']),cmd('lsof /dev/cu.usbserial-0001 /dev/tty.usbserial-0001'),note('A power LED, Android Bluetooth name or online CRM gateway does not prove the ESP32 answered over USB.'))
page('4. Get compiled firmware and flashing tools',steps(['In CRM Setup guide, expand New board firmware. Choose Download ESP32 firmware. If unavailable, ask the administrator to include the binary release; repository access is not needed.','Extract updata-esp32-firmware.tgz. The updata-esp32-firmware folder contains bootloader.bin, partition-table.bin, updata_hfp_bridge.bin, manifest.json, flash_args and INSTALL.txt. No source checkout is needed.','Install Python 3.12 from python.org/downloads. Create an isolated tool environment below; this does not build firmware.']),p('<b>Mac / Linux Terminal:</b>'),cmd('python3.12 -m venv "$HOME/.updata/flash-tools"\nsource "$HOME/.updata/flash-tools/bin/activate"'),p('<b>Windows Command Prompt (cmd.exe):</b>'),cmd('py -3.12 -m venv "%USERPROFILE%\\.updata\\flash-tools"\ncall "%USERPROFILE%\\.updata\\flash-tools\\Scripts\\activate.bat"'),p('<b>Then on either platform:</b>'),cmd('python -m pip install esptool==4.12.0\npython -m esptool version'),note('Activate the environment again in every new flashing command window. On Linux, ensure your user has USB serial permission; on Ubuntu this commonly means dialout membership and a new login. Do not run the gateway as root.'))
page('5. Inspect and back up the actual board',p('Stop gateways and serial tools. Set the actual port in your activated tool window:'),p('Mac/Linux (change the value for Linux):'),cmd('export UPDATA_ESP_PORT="/dev/cu.usbserial-0001"'),p('Windows cmd.exe:'),cmd('set "UPDATA_ESP_PORT=COM5"'),p('In every command below, replace PORT with the actual port. Do not type PORT literally.'),cmd('python -m esptool --chip esp32 --port PORT chip_id\npython -m esptool --chip esp32 --port PORT flash_id\npython -m espefuse --chip esp32 --port PORT summary'),note('Continue only for an unsecured original ESP32 with 4 MB flash. Stop for secure boot, flash encryption, different size/chip or unclear results. Do not change eFuses, force flags or erase-flash.'),p('If Connecting stalls, hold BOOT, press/release EN and release BOOT once it connects. For normal running, keep BOOT released.'),p('Make a private backup folder and use a fresh filename. Mac/Linux:'),cmd('mkdir -p "$HOME/updata-esp-backups"\nchmod 700 "$HOME/updata-esp-backups"\numask 077'),p('Windows: create a private folder under your user profile and restrict its access. Replace BACKUP.bin below with a new absolute file path in that folder.'),cmd('python -m esptool --chip esp32 --port PORT --baud 460800 --after no_reset read_flash 0 0x400000 BACKUP.bin\npython -m esptool --chip esp32 --port PORT --baud 460800 --before no_reset --after no_reset verify_flash 0 BACKUP.bin'),p('Run verify immediately, without reset/unplug/application startup. Stop unless it succeeds. Backups exclude eFuses and RAM; keep them private.'))
page('6. Flash the downloaded binary release',steps(['Open your activated flashing command window in the extracted updata-esp32-firmware folder. On Mac type cd plus a space, drag the folder into Terminal and press Enter. Windows uses cd /d plus the quoted folder path.','Read manifest.json: check release version, chip, 4 MB size and expected images. The archive is generated from an approved build and its file hashes are checked by the release packager. Do not mix versions or change flash offsets.','After the chip/security and verified backup checks, run the command below using the actual port.']),cmd('python -m esptool --chip esp32 --port PORT --baud 460800 write_flash @flash_args'),p('The included flash_args selects DIO / 40 MHz / 4 MB with bootloader at 0x1000, partition table at 0x8000 and application at 0x10000. Updating another partition layout may replace saved settings.'),steps(['Wait for successful flash completion. Release BOOT, press EN once and wait five seconds.','Return to the gateway package folder. Use its info command with your actual port.']),cmd('node bin/esp32-probe.mjs info --port PORT'),note('Checkpoint: firmware and board information must appear. If no reply remains, collect the complete flash output for support. Do not repeatedly flash or change the CRM key. The running binary protocol uses 921600 baud automatically; flashing uses 460800.'))
page('7. Link the computer to CRM',steps(['For a new phone: Add paired phone → name/SIM label → Create pairing code. For an existing card: stop its old gateway/service and choose Link computer on that same card. Do not create a duplicate.','Copy the generated pairing command, including actual API address, one-use code and PHONE_ID. Codes expire after ten minutes; a replacement code keeps the same card.','Run the generated command in the installed gateway package. Add the actual --port if necessary, especially with several bridges.']),p('Example only; replace values with the phone card’s generated values:'),cmd('node bin/updata-gateway.mjs pair --api "https://YOUR_CRM_HOST/api/v1" --code YOUR_CODE --profile PHONE_ID --port PORT\nnode bin/updata-gateway.mjs status --profile PHONE_ID --check-crm'),p('After paired:true and a successful CRM check, start:'),cmd('node bin/updata-gateway.mjs run --profile PHONE_ID'),p('If the saved USB port changed:'),cmd('node bin/updata-gateway.mjs run --profile PHONE_ID --port PORT'),note('Keep Terminal open. Computer must report online and ESP32 USB connected. status without --profile checks legacy/default credentials, which may differ. The frontend website address and API address can differ; use the generated command.'))
page('8. Security key, Android and sound',steps(['Open Phone setup. If the live board and CRM already report a matching provisioned key, keep it. If pending, hold BOOT while choosing Save security key; release after success. EN is reset.','Choose Pair a new phone for a two-minute discovery window. On Android open Bluetooth → Pair new device and select the exact Updata Phone Bridge name on the card. Confirm the pairing number if prompted.','Enable Phone calls for that Bluetooth device. Select Android’s default calling SIM, rather than Ask every time. Disconnect competing headsets/Mac hands-free connections if they take audio.','Choose Connect phone in CRM. For normal reconnection to an already bonded phone, try Connect phone before pairing again.','Open Sound & test call. Enter your own second phone’s international number. Confirm ownership and authorize one test call. Answer on that second phone.','Listen to the AI and say its requested phrase. Confirm the AI understands your response. Adjust AI volume if needed.','Choose Verify call audio only after speech works both ways. Confirm both checks and save. Repeat after a firmware/host change, even if an old check is green.']),note('Acceptance: current Computer online, USB connected, security key provisioned on the board, phone HFP connected, two-way audio verified and readiness OK.'),p('If the test reports an unavailable AI agent, the administrator must check the voice worker and LiveKit connection. Replacing the ESP32 key does not fix a server voice-service error.'))
page('9. Daily use and a different computer',p('Keep the computer awake and online, ESP32 connected and Android Bluetooth on. Start the gateway with its existing profile. No routine reflash or new key is required.'),p('<b>Mac login startup:</b> after foreground calls work, stop with Ctrl+C and run from the permanent package:'),cmd('node bin/updata-gateway.mjs service install --profile PHONE_ID\nnode bin/updata-gateway.mjs service status --profile PHONE_ID'),p('Before diagnostics or moving hosts, stop/remove that service:'),cmd('node bin/updata-gateway.mjs service uninstall --profile PHONE_ID'),p('Windows/Linux use the foreground run command; the built-in login installer supports macOS only.'),steps(['Move an existing bridge/phone: finish calls, stop the old gateway/service, connect USB on the new computer, install gateway and discover its new port.','If info returns Updata firmware, do not flash again. Use Link computer on the same CRM card with a fresh code, that phone’s profile and new port.','Keep a matching key and Bluetooth bond; reconnect and test real sound on the new host.','For another phone, use another prepared ESP32, distinct port/profile and separate gateway process. Do not open one bridge twice.']),p('Credentials stay in the computer user’s .updata/profiles/PHONE_ID folder. Link through CRM on the new computer; do not share credential files, tokens or keys.'))
page('10. Troubleshooting and handover',p('<b>Resource busy:</b> close screen, serial monitors, other gateways and login services. Identify the actual port owner; do not kill unrelated programs.'),p('<b>No reply:</b> release BOOT, reset EN once, retry. Check cable/port, bootloader response and approved firmware. A remembered Bluetooth entry does not verify USB.'),p('<b>Not linked:</b> check the correct profile/computer user. Use Link computer on the existing card and a new code. Do not rotate the calling key for missing computer credentials.'),p('<b>Computer online, USB unreachable:</b> CRM heartbeat is working, hardware control is not. Free/reconnect USB and follow section 3.'),p('<b>Firmware download missing:</b> ask the administrator to publish the compiled binary release. End users do not need repository access.'),p('<b>Bluetooth missing:</b> scan during Pair a new phone, enable Phone calls, choose default SIM and reconnect. Check current CRM status.'),p('<b>Failed AI/audio test:</b> check live USB, HFP, key, SIM and voice-worker readiness. Do not mark speech verified based on power or frame counts alone.'),p('<b>Record:</b> computer/Node version, gateway folder/version, firmware version, board identity/size, backup location, actual port, API URL, profile ID and real audio result. Share errors/logs with secrets and personal numbers removed.'),p('<b>Release:</b> this guide accompanies compiled firmware 0.1.4, original ESP32, ESP-IDF v5.5.6 build, DIO / 40 MHz / 4 MB. The firmware bundle contains only three binary images, manifest, flash arguments and instructions; no CRM/firmware source, provisioned keys, NVS snapshots or backups.'),p('<b>Official tools:</b> <a href="https://nodejs.org/en/download">Node.js</a> · <a href="https://www.python.org/downloads/">Python</a> · <a href="https://docs.espressif.com/projects/esptool/en/release-v4/esp32/esptool/basic-commands.html">Espressif esptool commands</a> · <a href="https://www.silabs.com/developer-tools/usb-to-uart-bridge-vcp-drivers">CP210x driver</a>'),note('This guide does not deploy CRM services or prove a specific physical board passed. Complete the live acceptance checks. Never use erase-flash or change security eFuses as a general repair.'))
css='''@page{size:A4;margin:17mm 16mm 18mm}*{box-sizing:border-box}body{margin:0;color:#182a3b;font:12px/1.43 Arial,sans-serif}section{break-after:page}section:last-child{break-after:auto}.eyebrow{font-size:9px;font-weight:bold;letter-spacing:1.5px;color:#16788d;margin-bottom:12px}h1{font-size:25px;line-height:1.16;margin:0 0 17px;color:#0e344a}p{margin:9px 0}pre{font:10px/1.43 'Courier New',monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#eef3f7;border-left:3px solid #248299;padding:9px 11px;margin:10px 0;break-inside:avoid}aside{background:#edf7f6;border:1px solid #b6dad4;padding:10px 12px;margin:13px 0;break-inside:avoid}ol{padding-left:20px}li{padding-left:3px;margin:8px 0}a{color:#086984}'''
(out/'updata-esp32-complete-setup.html').write_text('<!doctype html><html><head><meta charset="utf-8"><title>Updata ESP32 Binary Setup Guide</title><style>'+css+'</style></head><body>'+''.join(pages)+'</body></html>')
print('Created',len(pages),'sections; no repository/source installation instructions')
